  {
    Tweak t;
    t.id = L"network-force-1gbps-full-duplex";
    t.category = L"Network";
    t.subcategory = L"Rendimiento FPS";
    t.name = L"Forzar Ethernet a 1 Gbps Full Duplex";
    t.description = L"Fuerza la placa de red por cable activa a 1 Gbps Full Duplex en vez de dejarla en \"Auto Negociación\" — a veces la autonegociación se traba en una velocidad más baja o en half-duplex sin que se note, sobre todo con cables/switches viejos. Solo aplica a conexiones por cable: el WiFi no tiene esta opción (es inalámbrico, funciona distinto).";
    t.warning = L"Si tu cable, placa de red o switch/router no soportan de verdad 1 Gbps Full Duplex, la conexión puede cortarse o quedar inestable hasta que lo vuelvas a poner en \"Auto Negociación\" — desde acá mismo (queda un botón en \"Soluciones\" para volverlo a la normalidad) o a mano desde el Administrador de dispositivos.";
    t.buttonLabel = L"";
    t.confirmMessage = L"Este tweak es solo para conexión por cable (Ethernet). Si estás conectado por WiFi, no lo apliques — no tiene ningún efecto y solo vas a estar tocando la placa equivocada.\n\nAl aplicarlo, la placa de red se va a reiniciar un momento (se corta la conexión unos segundos y vuelve sola) para que el cambio de velocidad tome efecto.\n\n¿Continuar?";
    t.applyPs = LR"PS(
$ErrorActionPreference='SilentlyContinue'
$n=0
Get-NetAdapter -Physical | Where-Object { $_.MediaType -eq '802.3' -and $_.Status -eq 'Up' } | ForEach-Object {
  $name=$_.Name
  Set-NetAdapterAdvancedProperty -Name $name -RegistryKeyword '*SpeedDuplex' -RegistryValue 6 -NoRestart -ErrorAction SilentlyContinue
  Restart-NetAdapter -Name $name -ErrorAction SilentlyContinue
  $n++
}
if($n -eq 0){ Write-Output 'No hay un adaptador Ethernet activo.' } else { Write-Output "Ethernet forzado a 1 Gbps Full Duplex en $n adaptador(es)." }
)PS";
    t.actionOnly = true;
    t.premium = false;
    t.remoteOnly = false;
    t.laptopWarning = false;
    t.perfImpact = 0;
    t.risky = true;
    t.restart = true;
    t.recommended = false;
    t.needsAdmin = true;
    out.push_back(std::move(t));
  }
