    t.id = L"disable-vbs-core-isolation";
    t.category = L"Hardware";
    t.subcategory = L"Rendimiento FPS";
    t.name = L"Desactivar VBS / Aislamiento del núcleo (Memory Integrity)";
    t.description = L"Apaga la Virtualización basada en seguridad (VBS) y el Aislamiento del núcleo, que usan virtualización de hardware para aislar partes sensibles de Windows y le agregan overhead a las llamadas al sistema. El impacto real depende mucho de tu CPU: en varios Ryzen (5000/7000 en adelante) la diferencia en juegos suele ser mínima o casi imperceptible — puede que no notes nada. En algunas Intel (sobre todo generaciones más viejas) el golpe se nota más. Requiere reiniciar la PC.";
    t.warning = L"Baja un nivel real de protección contra malware que intenta explotar el kernel de Windows. Algunos juegos con anticheat a nivel kernel (por ejemplo Valorant/Vanguard) pueden pedir VBS activo para funcionar — si jugás alguno de esos, no lo desactives.";
    t.buttonLabel = L"";
    t.confirmMessage = L"";
    t.reg.push_back(R(HKEY_LOCAL_MACHINE, L"SYSTEM\\CurrentControlSet\\Control\\DeviceGuard", L"EnableVirtualizationBasedSecurity", REG_DWORD, L"0", L"1", false, false));
    t.reg.push_back(R(HKEY_LOCAL_MACHINE, L"SYSTEM\\CurrentControlSet\\Control\\DeviceGuard\\Scenarios\\HypervisorEnforcedCodeIntegrity", L"Enabled", REG_DWORD, L"0", L"1", false, false));
    t.applyPs = LR"PS(
$ErrorActionPreference='SilentlyContinue'
bcdedit /set hypervisorlaunchtype off | Out-Null
Write-Output 'VBS e integridad de memoria desactivados. Reinicia la PC.'
)PS";
    t.revertPs = LR"PS(
$ErrorActionPreference='SilentlyContinue'
bcdedit /set hypervisorlaunchtype auto | Out-Null
Write-Output 'VBS restaurado.'
)PS";
    t.actionOnly = false;
    t.premium = false;
    t.remoteOnly = false;
    t.laptopWarning = false;
    t.perfImpact = 0;
    t.risky = true;
    t.restart = true;
